@app.cell(hide_code=True)
def _(mo):
    mo.md(r"""
    # Himmelblau's function

    David Himmelblau introduced the two-dimensional, scalar multimodal function now called Himmelblau's function.

    It is defined as:

    $f(x,y) = (x^2+y-11)^2+(x+y^2-7)^2$

    and it looks like this:
    """)
    return


@app.function(hide_code=True)
def himmelblau(x, y):
    return (x**2 + y - 11) ** 2 + (x + y**2 - 7) ** 2


@app.cell(hide_code=True)
def _(go, mo, np):
    def plot_himmelblau():
        x = np.linspace(-6, 6, 200)
        y = np.linspace(-6, 6, 200)
        X, Y = np.meshgrid(x, y)
        Z = himmelblau(X, Y)
        Z_log = np.log10(Z)

        size = 500

        fig_surface = go.Figure(
            data=[
                go.Surface(
                    x=x,
                    y=y,
                    z=Z,
                    colorscale="magma_r",
                    showscale=False,
                )
            ]
        )
        fig_surface.update_layout(
            dragmode="turntable",
            autosize=False,
            width=size,
            height=size,
        )

        colorbar = dict(
            tickmode="array",
            tickvals=[-1, 0, 1, 2, 3],
            ticktext=["0.1", "1", 10, 100, 1000],
            ticks="outside",
        )
        fig_heatmap = go.Figure(
            data=go.Heatmap(
                x=x,
                y=y,
                z=Z_log,
                colorscale="magma_r",
                colorbar=colorbar,
                hovertemplate="x: %{x:.2f}<br>"
                + "y: %{y:.2f}<br>"
                + "z: %{text:.2f}"
                + "<extra></extra>",
                text=Z,
            )
        )

        fig_heatmap.update_layout(
            autosize=False,
            width=size,
            height=size,
        )

        return mo.hstack([fig_surface, fig_heatmap], widths="equal")

    plot_himmelblau()
    return


